window.AUTH=window.AUTH||{};window.AUTH["88-1203"]={"d":"88-1203","id":"1989/88-1203","n":"Hoffmann-LaRoche Inc. v. Sperling","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the Equal Employment Opportunity Commission as amicus curiae supporting respondents","date":"","url":"https://www.justice.gov/osg/media/212646/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/hoffman-la-roche-inc-petitioner-v-richard-sperling-et-al","toa":false,"n":60}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep493/usrep493165/usrep493165.pdf","tr":false,"items":[{"t":"case","label":"Gulf Oil Co. v. Bernard","cite":"452 U.S. 89","y":1981,"id":"1980/80-441","sc":1,"op":3,"sum":"The District Court in imposing the order in question abused its discretion under the Federal Rules of Civil Procedure.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Braunstein v. Eastern Photographic Labs, Inc.","cite":"600 F.2d 335","y":1978,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/600/335/","op":1,"by":{"0":""}},{"t":"case","label":"Similarly, in Woods v. New York Life Insurance Co.","cite":"686 F.2d 578","y":1982,"url":"https://www.courtlistener.com/c/F.2d/686/578/","op":1,"by":{"0":""}},{"t":"case","label":"Link v. Wabash R.R.","cite":"370 U.S. 626","y":1962,"id":"1961/422","sc":1,"op":2,"sum":"The Court held that a court has the right to clear its calendar of cases that have been dormant because of inaction on the part of the plaintiff without any motion from the defense. This right has long been understood as one of the inherent powers of the court and no law explicitly restricts it.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Harris v. Nelson","cite":"394 U.S. 286","y":1969,"id":"1968/199","sc":1,"sum":"A state prisoner filed a habeas corpus petition in the Federal District Court, alleging that the admission of certain evidence at his trial was improper because the evidence had been seized incident to an arrest based upon information from an unreliable informant. The District Court ordered an evidentiary hearing and the prisoner served on respondent a series of interrogatories pursuant to Rule 33 of the Federal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Alaska Airlines, Inc. v. Brock","cite":"480 U.S. 678","y":1987,"id":"1986/85-920","sc":1,"sum":"Section 43(f)(3)'s legislative-veto provision is severable from the remainder of the EPP program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"NLRB v. Plasterers' Union","cite":"404 U.S. 116","y":1971,"id":"1971/70-63","sc":1,"by":{"0":""}},{"t":"case","label":"Girouard v. United States","cite":"328 U.S. 61","y":1946,"id":"scdb/1945-039","sc":1,"sum":"An alien who is willing to take the oath of allegiance and to serve in the army as a non-combatant but who, because of religious scruples, is unwilling to bear arms in defense of this country may be admitted to citizenship under the Nationality Act of 1940, as amended by the Act of March 27, 1942. United States v. Schwimmer, 279 U. S. 644; United States i'. Macintosh, 283 U. S. 605; and United States v. Bland, 283 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Northwest Airlines, Inc. v. Transport Workers Union","cite":"451 U.S. 77","y":1981,"id":"1980/79-1056","sc":1,"sum":"Petitioner has neither a federal statutory nor a federal common-law right to contribution from respondent unions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"National Labor Relations Act. See Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"op":2,"by":{"0":""}},{"t":"case","label":"United States v. Cook","cite":"795 F.2d 987","y":1986,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/795/987/","op":1,"by":{"0":""}},{"t":"case","label":"McKenna v. Champion International Corp.","cite":"747 F.2d 1211","y":1984,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/747/1211/","op":1,"by":{"0":""}},{"t":"case","label":"Dolan v. Project Construction Corp.","cite":"725 F.2d 1263","y":1984,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/725/1263/","op":1,"by":{"0":""}},{"t":"case","label":"Partlow v. Jewish Orphans' Home, Inc.","cite":"645 F.2d 757","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/645/757/","op":1,"by":{"0":""}},{"t":"case","label":"Kinney Shoe Corp. v. Vorhes","cite":"564 F.2d 859","y":1977,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/564/859/","op":1,"by":{"0":""}},{"t":"case","label":"Shain v. Armour & Co.","cite":"40 F. Supp. 488","y":1941,"court":"W.D. Ky.","url":"https://www.courtlistener.com/c/F.%20Supp./40/488/","by":{"0":""}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"sum":"Section 204 (a) (1) of the Social Security Act (Act) authorizes the Secretary of the Department of Health, Education, and Welfare to recoup erroneous overpayments made to a beneficiary under the old-age, survivors', or disability insurance programs by decreasing future payments to which the overpaid person is entitled. However, § 204 (b) commands that \"there shall be no adjustment of payments to, or recovery by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"LaChapelle v. Owens-Illinois, Inc.","cite":"513 F.2d 286","y":1975,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/513/286/","by":{"0":""}},{"t":"case","label":"Colgrove v. Battin","cite":"413 U.S. 149","y":1973,"id":"1972/71-1442","sc":1,"sum":"Local federal court rule providing that a jury for the trial of civil cases shall consist of six persons comports with the Seventh Amendment requirement and the coextensive statutory requirement of 28 U. S. C. § 2072 that the right of trial by jury be preserved in suits at common law, and is not inconsistent with Fed. Rule Civ. Proc. 48 that deals only with parties' stipulations regarding jury size. Pp. 151-164. 456 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Pan American World Airways, Inc. v. United States District Court","cite":"523 F.2d 1073","y":1975,"url":"https://www.courtlistener.com/c/F.2d/523/1073/","by":{"0":""}},{"t":"case","label":"Roadway Express, Inc. v. Piper","cite":"447 U.S. 752","y":1980,"id":"1979/79-701","sc":1,"sum":"Respondents were counsel for the plaintiffs in a civil rights class action in Federal District Court against petitioner alleging that its employment policies discriminated on the basis of race. Because respondents failed to comply with orders relating to discovery and the filing of briefs, petitioner moved to dismiss the suit and requested an award of attorney's fees and court costs under Federal Rule of Civil …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. New York Telephone Co.","cite":"434 U.S. 159","y":1977,"id":"1977/76-835","sc":1,"sum":"On the basis of an FBI affidavit stating that certain individuals were conducting an illegal gambling enterprise at a specified New York City address and that there was probable cause to believe that two telephones with different numbers were being used there to further the illegal activity, the District Court authorized the FBI to install and use pen registers with respect to the two telephones, and directed …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Miner v. Atlass","cite":"363 U.S. 641","y":1960,"id":"1959/156","sc":1,"sum":"A Federal District Court sitting in admiralty has no power to order the taking of oral depositions for the purpose of discovery only; and Rule 32 of the Admiralty Rules of the District Court for the Northern District of Illinois, purporting to authorize the taking of such depositions, is invalid for want of authority in the District Court to promulgate it.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Luce v. United States","cite":"469 U.S. 38","id":"1984/83-912","sc":1,"sum":"To raise and preserve for review the claim of improper impeachment with a prior conviction, a defendant must testify. To perform the weighing of the prior conviction's probative value against its prejudicial effect, as required by Rule 609(a)(1), the reviewing court must know the precise nature of the defendant's testimony, which is unknowable when, as here, the defendant does not testify. Any possible harm flowing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Republic International Corp. v. Amco Engineers, Inc.","cite":"516 F.2d 161","y":1975,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/516/161/","by":{"0":""}},{"t":"case","label":"Brown v. Cameron-Brown Co.","cite":"652 F.2d 375","y":1981,"url":"https://www.courtlistener.com/c/F.2d/652/375/","by":{"0":""}},{"t":"case","label":"Franquez v. United States","cite":"604 F.2d 1239","y":1979,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/604/1239/","by":{"0":""}},{"t":"case","label":"Heileman Brewing Co. v. Joseph Oat Corp.","cite":"871 F.2d 648","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/871/648/","sum":"Recognizing inherent authority that \"forms the basis for continued development of procedural techniques\".","sumSrc":"brief:0","by":{"0":""}},{"t":"case","label":"HMG Property Investors, Inc. v. Parque Industrial Rio Canas","cite":"847 F.2d 908","y":1988,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/847/908/","by":{"0":""}},{"t":"case","label":"Pentland v. Dravo Corp.","cite":"152 F.2d 851","y":1945,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/152/851/","by":{"0":""}},{"t":"case","label":"United States v. American Optical Co.","cite":"97 F. Supp. 66","y":1951,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp./97/66/","by":{"0":""}},{"t":"case","label":"Weeks v. Bareco Oil Co.","cite":"125 F.2d 84","y":1941,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/125/84/","by":{"0":""}},{"t":"case","label":"Oppenheimer v. F.J. Young & Co.","cite":"144 F.2d 387","y":1944,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/144/387/","by":{"0":""}},{"t":"case","label":"Sam Fox Publishing Co. v. United States","cite":"366 U.S. 683","y":1961,"id":"1960/56","sc":1,"sum":"Appellants were not bound by the parts of the decree as to which they sought intervention; they were not entitled to intervene as of right; the order denying intervention was not appealable; and the appeal is dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Dickinson v. Burnham","cite":"197 F.2d 973","url":"https://www.courtlistener.com/c/F.2d/197/973/","by":{"0":""}},{"t":"case","label":"Women's Catholic Order of Foresters v. City of Ennis","cite":"112 F.2d 270","y":1941,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/112/270/","sum":"Describing class suit commenced before the effective date of the Civil Rules in which notice was given to members of the class.","sumSrc":"brief:0","by":{"0":""}},{"t":"case","label":"Payne v. Travenol Laboratories, Inc.","cite":"673 F.2d 798","url":"https://www.courtlistener.com/c/F.2d/673/798/","by":{"0":""}},{"t":"case","label":"Avery v. Secretary of HHS","cite":"762 F.2d 158","y":1985,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/762/158/","by":{"0":""}},{"t":"case","label":"Cort v. Ash","cite":"422 U.S. 66","y":1975,"id":"1974/73-1908","sc":1,"sum":"Respondent stockholder brought this action seeking damages in favor of petitioner Bethlehem Steel Corp., a Delaware corporation, and injunctive relief because of advertisements in connection with the 1972 Presidential election that petitioner corporate directors had authorized from general corporate funds in alleged violation of 18 U. S. C. § 610, which prohibits corporations from making contributions or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Touche Ross & Co. v. Redington","cite":"442 U.S. 560","y":1979,"id":"1978/78-309","sc":1,"sum":"There is no implied private cause of action for damages under § 17 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Cannon v. University of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Anderson v. Mt. Clemens Pottery Co.","cite":"328 U.S. 680","y":1946,"id":"scdb/1945-099","sc":1,"sum":"Respondent produces pottery for interstate commerce. Its employees enter the plant and punch time clocks during a period of 14 minutes before the regular starting time for productive work. They walk from the time clocks to their places of work within the plant and make'various preparations for the start of productive work. After the regular quitting time, they were allowed a 14-minute period to punch out and leave …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Universities Research Ass'n v. Coutu","cite":"450 U.S. 754","y":1981,"id":"1980/78-1945","sc":1,"sum":"The Davis-Bacon Act does not confer upon an employee a private right of action for back wages under a contract that has been administratively determined not to call for work subject to the Act and thus does not contain prevailing wage stipulations. Pp. 767-784. UNIVERSITIES RESEARCH ASSN. v. COUTU (a) While requiring that certain stipulations be placed in federal construction contracts for the benefit of mechanics …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Steiner v. Mitchell","cite":"350 U.S. 247","y":1956,"id":"1955/22","sc":1,"sum":"Changing clothes and showering are parts of their \"principal,\" rather than their \"preliminary\" or \"postliminary,\" activities, within the meaning of § 4 (a) (2) of the -Portal-to-Portal Act, and the time spent in these activities must be counted in measuring the work-time for which compensation is required by the Fair Labor Standards Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Smith v. Stark Trucking, Inc.","cite":"53 F. Supp. 826","y":1943,"court":"N.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp./53/826/","by":{"0":""}},{"t":"case","label":"Albemarle Paper Co. v. Moody","cite":"422 U.S. 405","y":1975,"id":"1974/74-389","sc":1,"sum":"The Court held that backpay should be awarded based on a court’s discretion. The decision in this case should be considered in light of the goals of the Equal Employment Opportunity Act. Because the prospect of a backpay award could ensure the use of equal employment practices, it serves the purposes of the Act and should be awarded in this case.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Levine v. Lane Bryant","cite":"700 F. Supp. 949","y":1988,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp./700/949/","by":{"0":""}},{"t":"case","label":"Vivone v. Acme Markets","cite":"687 F. Supp. 168","y":1988,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./687/168/","by":{"0":""}},{"t":"case","label":"Morelock v. NCR Corp.","cite":"586 F.2d 1096","y":1978,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/586/1096/","by":{"0":""}},{"t":"case","label":"O'Connell v. Champion International Corp.","cite":"812 F.2d 393","y":1987,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/812/393/","by":{"0":""}},{"t":"case","label":"Mistretta v. Sandia Corp.","cite":"639 F.2d 588","y":1980,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/639/588/","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(b)"],"stext":{"head":"§626. Recordkeeping, investigation, and enforcement","paras":[[0,"(a) Attendance of witnesses; investigations, inspections, records, and homework regulations"],[0,"The Equal Employment Opportunity Commission shall have the power to make investigations and require the keeping of records necessary or appropriate for the administration of this chapter in accordance with the powers and procedures provided in sections 209 and 211 of this title."],[0,"(b) Enforcement; prohibition of age discrimination under fair labor standards; unpaid minimum wages and unpaid overtime compensation; liquidated damages; judicial relief; conciliation, conference, and persuasion"],[0,"The provisions of this chapter shall be enforced in accordance with the powers, remedies, and procedures provided in sections 211(b), 216 (except for subsection (a) thereof), and 217 of this title, and subsection (c) of this section. Any act prohibited under section 623 of this title shall be deemed to be a prohibited act under section 215 of this title. Amounts owing to a person as a result of a violation of this chapter shall be deemed to be unpaid minimum wages or unpaid overtime compensation for purposes of sections 216 and 217 of this title: Provided, That liquidated damages shall be payable only in cases of willful violations of this chapter. In any action brought to enforce this chapter the court shall have jurisdiction to grant such legal or equitable relief as may be appropriate to effectuate the purposes of this chapter, including without limitation judgments compelling employment, reinstatement or promotion, or enforcing the liability for amounts deemed to be unpaid minimum wages or unpaid overtime compensation under this section. Before instituting any action under this section, the Equal Employment Opportunity Commission shall attempt to eliminate the discriminatory practice or practices alleged, and to effect voluntary compliance with the requirements of this chapter through informal methods of conciliation, conference, and persuasion."],[0,"(c) Civil actions; persons aggrieved; jurisdiction; judicial relief; termination of individual action upon commencement of action by Commission; jury trial"],[0,"(1) Any person aggrieved may bring a civil action in any court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter: Provided, That the right of any person to bring such action shall terminate upon the commencement of an action by the Equal Employment Opportunity Commission to enforce the right of such employee under this chapter."],[0,"(2) In an action brought under paragraph (1), a person shall be entitled to a trial by jury of any issue of fact in any such action for recovery of amounts owing as a result of a violation of this chapter, regardless of whether equitable relief is sought by any party in such action."],[0,"(d) Filing of charge with Commission; timeliness; conciliation, conference, and persuasion; unlawful practice"],[0,"(1) No civil action may be commenced by an individual under this section until 60 days after a charge alleging unlawful discrimination has been filed with the Equal Employment Opportunity Commission. Such a charge shall be filed—"],[1,"(A) within 180 days after the alleged unlawful practice occurred; or"],[1,"(B) in a case to which section 633(b) of this title applies, within 300 days after the alleged unlawful practice occurred, or within 30 days after receipt by the individual of notice of termination of proceedings under State law, whichever is earlier."],[0,"(2) Upon receiving such a charge, the Commission shall promptly notify all persons named in such charge as prospective defendants in the action and shall promptly seek to eliminate any alleged unlawful practice by informal methods of conciliation, conference, and persuasion."],[0,"(3) For purposes of this section, an unlawful practice occurs, with respect to discrimination in compensation in violation of this chapter, when a discriminatory compensation decision or other practice is adopted, when a person becomes subject to a discriminatory compensation decision or other practice, or when a person is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(e) Reliance on administrative rulings; notice of dismissal or termination; civil action after receipt of notice"],[0,"Section 259 of this title shall apply to actions under this chapter. If a charge filed with the Commission under this chapter is dismissed or the proceedings of the Commission are otherwise terminated by the Commission, the Commission shall notify the person aggrieved. A civil action may be brought under this section by a person defined in section 630(a) of this title against the respondent named in the charge within 90 days after the date of the receipt of such notice."],[0,"(f) Waiver"],[0,"(1) An individual may not waive any right or claim under this chapter unless the waiver is knowing and voluntary. Except as provided in paragraph (2), a waiver may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) the waiver is part of an agreement between the individual and the employer that is written in a manner calculated to be understood by such individual, or by the average individual eligible to participate;"],[1,"(B) the waiver specifically refers to rights or claims arising under this chapter;"],[1,"(C) the individual does not waive rights or claims that may arise after the date the waiver is executed;"],[1,"(D) the individual waives rights or claims only in exchange for consideration in addition to anything of value to which the individual already is entitled;"],[1,"(E) the individual is advised in writing to consult with an attorney prior to executing the agreement;"],[1,"(F)(i) the individual is given a period of at least 21 days within which to consider the agreement; or"],[1,"(ii) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the individual is given a period of at least 45 days within which to consider the agreement;"],[1,"(G) the agreement provides that for a period of at least 7 days following the execution of such agreement, the individual may revoke the agreement, and the agreement shall not become effective or enforceable until the revocation period has expired;"],[1,"(H) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the employer (at the commencement of the period specified in subparagraph (F)) informs the individual in writing in a manner calculated to be understood by the average individual eligible to participate, as to—"],[2,"(i) any class, unit, or group of individuals covered by such program, any eligibility factors for such program, and any time limits applicable to such program; and"],[2,"(ii) the job titles and ages of all individuals eligible or selected for the program, and the ages of all individuals in the same job classification or organizational unit who are not eligible or selected for the program."],[0,"(2) A waiver in settlement of a charge filed with the Equal Employment Opportunity Commission, or an action filed in court by the individual or the individual's representative, alleging age discrimination of a kind prohibited under section 623 or 633a of this title may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) subparagraphs (A) through (E) of paragraph (1) have been met; and"],[1,"(B) the individual is given a reasonable period of time within which to consider the settlement agreement."],[0,"(3) In any dispute that may arise over whether any of the requirements, conditions, and circumstances set forth in subparagraph (A), (B), (C), (D), (E), (F), (G), or (H) of paragraph (1), or subparagraph (A) or (B) of paragraph (2), have been met, the party asserting the validity of a waiver shall have the burden of proving in a court of competent jurisdiction that a waiver was knowing and voluntary pursuant to paragraph (1) or (2)."],[0,"(4) No waiver agreement may affect the Commission's rights and responsibilities to enforce this chapter. No waiver may be used to justify interfering with the protected right of an employee to file a charge or participate in an investigation or proceeding conducted by the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/626?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§626. Recordkeeping, investigation, and enforcement","tname":"Labor","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(b)"],"stext":{"head":"§216. Penalties","paras":[[0,"(a) Fines and imprisonment"],[0,"Any person who willfully violates any of the provisions of section 215 of this title shall upon conviction thereof be subject to a fine of not more than $10,000, or to imprisonment for not more than six months, or both. No person shall be imprisoned under this subsection except for an offense committed after the conviction of such person for a prior offense under this subsection."],[0,"(b) Damages; right of action; attorney's fees and costs; termination of right of action"],[0,"Any employer who violates the provisions of section 206 or section 207 of this title shall be liable to the employee or employees affected in the amount of their unpaid minimum wages, or their unpaid overtime compensation, as the case may be, and in an additional equal amount as liquidated damages. Any employer who violates the provisions of section 215(a)(3) or 218d of this title shall be liable for such legal or equitable relief as may be appropriate to effectuate the purposes of section 215(a)(3) or 218d of this title, including without limitation employment, reinstatement, promotion, and the payment of wages lost and an additional equal amount as liquidated damages. Any employer who violates section 203(m)(2)(B) of this title shall be liable to the employee or employees affected in the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and in an additional equal amount as liquidated damages. An action to recover the liability prescribed in the preceding sentences may be maintained against any employer (including a public agency) in any Federal or State court of competent jurisdiction by any one or more employees for and in behalf of himself or themselves and other employees similarly situated. No employee shall be a party plaintiff to any such action unless he gives his consent in writing to become such a party and such consent is filed in the court in which such action is brought. The court in such action shall, in addition to any judgment awarded to the plaintiff or plaintiffs, allow a reasonable attorney's fee to be paid by the defendant, and costs of the action. The right provided by this subsection to bring an action by or on behalf of any employee, and the right of any employee to become a party plaintiff to any such action, shall terminate upon the filing of a complaint by the Secretary of Labor in an action under section 217 of this title in which (1) restraint is sought of any further delay in the payment of unpaid minimum wages, or the amount of unpaid overtime compensation, as the case may be, owing to such employee under section 206 or section 207 of this title by an employer liable therefor under the provisions of this subsection or (2) legal or equitable relief is sought as a result of alleged violations of section 215(a)(3) or 218d of this title."],[0,"(c) Payment of wages and compensation; waiver of claims; actions by the Secretary; limitation of actions"],[0,"The Secretary is authorized to supervise the payment of the unpaid minimum wages or the unpaid overtime compensation owing to any employee or employees under section 206 or section 207 of this title, and the agreement of any employee to accept such payment shall upon payment in full constitute a waiver by such employee of any right he may have under subsection (b) of this section to such unpaid minimum wages or unpaid overtime compensation and an additional equal amount as liquidated damages. The Secretary may bring an action in any court of competent jurisdiction to recover the amount of unpaid minimum wages or overtime compensation and an equal amount as liquidated damages. The right provided by subsection (b) to bring an action by or on behalf of any employee to recover the liability specified in the first sentence of such subsection and of any employee to become a party plaintiff to any such action shall terminate upon the filing of a complaint by the Secretary in an action under this subsection in which a recovery is sought of unpaid minimum wages or unpaid overtime compensation under sections 206 and 207 of this title or liquidated or other damages provided by this subsection owing to such employee by an employer liable under the provisions of subsection (b), unless such action is dismissed without prejudice on motion of the Secretary. Any sums thus recovered by the Secretary of Labor on behalf of an employee pursuant to this subsection shall be held in a special deposit account and shall be paid, on order of the Secretary of Labor, directly to the employee or employees affected. Any such sums not paid to an employee because of inability to do so within a period of three years shall be covered into the Treasury of the United States as miscellaneous receipts. In determining when an action is commenced by the Secretary of Labor under this subsection for the purposes of the statutes of limitations provided in section 6(a) of the Portal-to-Portal Act of 1947 [29 U.S.C. 255(a)], it shall be considered to be commenced in the case of any individual claimant on the date when the complaint is filed if he is specifically named as a party plaintiff in the complaint, or if his name did not so appear, on the subsequent date on which his name is added as a party plaintiff in such action. The authority and requirements described in this subsection shall apply with respect to a violation of section 203(m)(2)(B) of this title, as appropriate, and the employer shall be liable for the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and an additional equal amount as liquidated damages."],[0,"(d) Savings provisions"],[0,"In any action or proceeding commenced prior to, on, or after August 8, 1956, no employer shall be subject to any liability or punishment under this chapter or the Portal-to-Portal Act of 1947 [29 U.S.C. 251 et seq.] on account of his failure to comply with any provision or provisions of this chapter or such Act (1) with respect to work heretofore or hereafter performed in a workplace to which the exemption in section 213(f) of this title is applicable, (2) with respect to work performed in Guam, the Canal Zone or Wake Island before the effective date of this amendment of subsection (d), or (3) with respect to work performed in a possession named in section 206(a)(3) 1 of this title at any time prior to the establishment by the Secretary, as provided therein, of a minimum wage rate applicable to such work."],[0,"(e) Civil penalties for certain violations"],[0,"(1)(A) Any person who violates the provisions of sections 2 212 or 213(c) of this title, relating to child labor, or any regulation issued pursuant to such sections, shall be subject to a civil penalty not to exceed—"],[1,"(i) $11,000 for each employee who was the subject of such a violation; or"],[1,"(ii) $50,000 with regard to each such violation that causes the death or serious injury of any employee under the age of 18 years, which penalty may be doubled where the violation is a repeated or willful violation."],[0,"(B) For purposes of subparagraph (A), the term \"serious injury\" means—"],[1,"(i) permanent loss or substantial impairment of one of the senses (sight, hearing, taste, smell, tactile sensation);"],[1,"(ii) permanent loss or substantial impairment of the function of a bodily member, organ, or mental faculty, including the loss of all or part of an arm, leg, foot, hand or other body part; or"],[1,"(iii) permanent paralysis or substantial impairment that causes loss of movement or mobility of an arm, leg, foot, hand or other body part."],[0,"(2) Any person who repeatedly or willfully violates section 206 or 207 of this title, relating to wages, shall be subject to a civil penalty not to exceed $1,100 for each such violation. Any person who violates section 203(m)(2)(B) of this title shall be subject to a civil penalty not to exceed $1,100 for each such violation, as the Secretary determines appropriate, in addition to being liable to the employee or employees affected for all tips unlawfully kept, and an additional equal amount as liquidated damages, as described in subsection (b)."],[0,"(3) In determining the amount of any penalty under this subsection, the appropriateness of such penalty to the size of the business of the person charged and the gravity of the violation shall be considered. The amount of any penalty under this subsection, when finally determined, may be—"],[1,"(A) deducted from any sums owing by the United States to the person charged;"],[1,"(B) recovered in a civil action brought by the Secretary in any court of competent jurisdiction, in which litigation the Secretary shall be represented by the Solicitor of Labor; or"],[1,"(C) ordered by the court, in an action brought for a violation of section 215(a)(4) of this title or a repeated or willful violation of section 215(a)(2) of this title, to be paid to the Secretary."],[0,"(4) Any administrative determination by the Secretary of the amount of any penalty under this subsection shall be final, unless within 15 days after receipt of notice thereof by certified mail the person charged with the violation takes exception to the determination that the violations for which the penalty is imposed occurred, in which event final determination of the penalty shall be made in an administrative proceeding after opportunity for hearing in accordance with section 554 of title 5 and regulations to be promulgated by the Secretary."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/216?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§216. Penalties","tname":"Labor","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","subs":["(d)"],"by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","stext":{"head":"§623. Prohibition of age discrimination","paras":[[0,"(a) Employer practices"],[0,"It shall be unlawful for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's age;"],[1,"(2) to limit, segregate, or classify his employees in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's age; or"],[1,"(3) to reduce the wage rate of any employee in order to comply with this chapter."],[0,"(b) Employment agency practices"],[0,"It shall be unlawful for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of such individual's age, or to classify or refer for employment any individual on the basis of such individual's age."],[0,"(c) Labor organization practices"],[0,"It shall be unlawful for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his age;"],[1,"(2) to limit, segregate, or classify its membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's age;"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Opposition to unlawful practices; participation in investigations, proceedings, or litigation"],[0,"It shall be unlawful for an employer to discriminate against any of his employees or applicants for employment, for an employment agency to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because such individual, member or applicant for membership has opposed any practice made unlawful by this section, or because such individual, member or applicant for membership has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under this chapter."],[0,"(e) Printing or publication of notice or advertisement indicating preference, limitation, etc."],[0,"It shall be unlawful for an employer, labor organization, or employment agency to print or publish, or cause to be printed or published, any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, indicating any preference, limitation, specification, or discrimination, based on age."],[0,"(f) Lawful practices; age an occupational qualification; other reasonable factors; laws of foreign workplace; seniority system; employee benefit plans; discharge or discipline for good cause"],[0,"It shall not be unlawful for an employer, employment agency, or labor organization—"],[1,"(1) to take any action otherwise prohibited under subsections (a), (b), (c), or (e) of this section where age is a bona fide occupational qualification reasonably necessary to the normal operation of the particular business, or where the differentiation is based on reasonable factors other than age, or where such practices involve an employee in a workplace in a foreign country, and compliance with such subsections would cause such employer, or a corporation controlled by such employer, to violate the laws of the country in which such workplace is located;"],[1,"(2) to take any action otherwise prohibited under subsection (a), (b), (c), or (e) of this section—"],[2,"(A) to observe the terms of a bona fide seniority system that is not intended to evade the purposes of this chapter, except that no such seniority system shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title because of the age of such individual; or"],[2,"(B) to observe the terms of a bona fide employee benefit plan—"],[3,"(i) where, for each benefit or benefit package, the actual amount of payment made or cost incurred on behalf of an older worker is no less than that made or incurred on behalf of a younger worker, as permissible under section 1625.10, title 29, Code of Federal Regulations (as in effect on June 22, 1989); or"],[3,"(ii) that is a voluntary early retirement incentive plan consistent with the relevant purpose or purposes of this chapter."],[1,"Notwithstanding clause (i) or (ii) of subparagraph (B), no such employee benefit plan or voluntary early retirement incentive plan shall excuse the failure to hire any individual, and no such employee benefit plan shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title, because of the age of such individual. An employer, employment agency, or labor organization acting under subparagraph (A), or under clause (i) or (ii) of subparagraph (B), shall have the burden of proving that such actions are lawful in any civil enforcement proceeding brought under this chapter; or"],[1,"(3) to discharge or otherwise discipline an individual for good cause."],[0,"(g) Repealed. Pub. L. 101–239, title VI, §6202(b)(3)(C)(i), Dec. 19, 1989, 103 Stat. 2233"],[0,"(h) Practices of foreign corporations controlled by American employers; foreign employers not controlled by American employers; factors determining control"],[0,"(1) If an employer controls a corporation whose place of incorporation is in a foreign country, any practice by such corporation prohibited under this section shall be presumed to be such practice by such employer."],[0,"(2) The prohibitions of this section shall not apply where the employer is a foreign person not controlled by an American employer."],[0,"(3) For the purpose of this subsection the determination of whether an employer controls a corporation shall be based upon the—"],[1,"(A) interrelation of operations,"],[1,"(B) common management,"],[1,"(C) centralized control of labor relations, and"],[1,"(D) common ownership or financial control,"],[0,"of the employer and the corporation."],[0,"(i) Employee pension benefit plans; cessation or reduction of benefit accrual or of allocation to employee account; distribution of benefits after attainment of normal retirement age; compliance; highly compensated employees"],[0,"(1) Except as otherwise provided in this subsection, it shall be unlawful for an employer, an employment agency, a labor organization, or any combination thereof to establish or maintain an employee pension benefit plan which requires or permits—"],[1,"(A) in the case of a defined benefit plan, the cessation of an employee's benefit accrual, or the reduction of the rate of an employee's benefit accrual, because of age, or"],[1,"(B) in the case of a defined contribution plan, the cessation of allocations to an employee's account, or the reduction of the rate at which amounts are allocated to an employee's account, because of age."],[0,"(2) Nothing in this section shall be construed to prohibit an employer, employment agency, or labor organization from observing any provision of an employee pension benefit plan to the extent that such provision imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(3) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(A) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(B) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title and section 401(a)(14)(C) of title 26, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title or section 411(a)(3)(B) of title 26, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The provisions of this paragraph shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations shall provide for the application of the preceding provisions of this paragraph to all employee pension benefit plans subject to this subsection and may provide for the application of such provisions, in the case of any such employee, with respect to any period of time within a plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/623?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§623. Prohibition of age discrimination","tname":"Labor","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)"],"stext":{"head":"§1292. Interlocutory decisions","paras":[[0,"(a) Except as provided in subsections (c) and (d) of this section, the courts of appeals shall have jurisdiction of appeals from:"],[1,"(1) Interlocutory orders of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, or of the judges thereof, granting, continuing, modifying, refusing or dissolving injunctions, or refusing to dissolve or modify injunctions, except where a direct review may be had in the Supreme Court;"],[1,"(2) Interlocutory orders appointing receivers, or refusing orders to wind up receiverships or to take steps to accomplish the purposes thereof, such as directing sales or other disposals of property;"],[1,"(3) Interlocutory decrees of such district courts or the judges thereof determining the rights and liabilities of the parties to admiralty cases in which appeals from final decrees are allowed."],[0,"(b) When a district judge, in making in a civil action an order not otherwise appealable under this section, shall be of the opinion that such order involves a controlling question of law as to which there is substantial ground for difference of opinion and that an immediate appeal from the order may materially advance the ultimate termination of the litigation, he shall so state in writing in such order. The Court of Appeals which would have jurisdiction of an appeal of such action may thereupon, in its discretion, permit an appeal to be taken from such order, if application is made to it within ten days after the entry of the order: Provided, however, That application for an appeal hereunder shall not stay proceedings in the district court unless the district judge or the Court of Appeals or a judge thereof shall so order."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from an interlocutory order or decree described in subsection (a) or (b) of this section in any case over which the court would have jurisdiction of an appeal under section 1295 of this title; and"],[1,"(2) of an appeal from a judgment in a civil action for patent infringement which would otherwise be appealable to the United States Court of Appeals for the Federal Circuit and is final except for an accounting."],[0,"(d)(1) When the chief judge of the Court of International Trade issues an order under the provisions of section 256(b) of this title, or when any judge of the Court of International Trade, in issuing any other interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(2) When the chief judge of the United States Court of Federal Claims issues an order under section 798(b) of this title, or when any judge of the United States Court of Federal Claims, in issuing an interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(3) Neither the application for nor the granting of an appeal under this subsection shall stay proceedings in the Court of International Trade or in the Court of Federal Claims, as the case may be, unless a stay is ordered by a judge of the Court of International Trade or of the Court of Federal Claims or by the United States Court of Appeals for the Federal Circuit or a judge of that court."],[0,"(4)(A) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction of an appeal from an interlocutory order of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, granting or denying, in whole or in part, a motion to transfer an action to the United States Court of Federal Claims under section 1631 of this title."],[0,"(B) When a motion to transfer an action to the Court of Federal Claims is filed in a district court, no further proceedings shall be taken in the district court until 60 days after the court has ruled upon the motion. If an appeal is taken from the district court's grant or denial of the motion, proceedings shall be further stayed until the appeal has been decided by the Court of Appeals for the Federal Circuit. The stay of proceedings in the district court shall not bar the granting of preliminary or injunctive relief, where appropriate and where expedition is reasonably necessary. However, during the period in which proceedings are stayed as provided in this subparagraph, no transfer to the Court of Federal Claims pursuant to the motion shall be carried out."],[0,"(e) The Supreme Court may prescribe rules, in accordance with section 2072 of this title, to provide for an appeal of an interlocutory decision to the courts of appeals that is not otherwise provided for under subsection (a), (b), (c), or (d)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1292?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1292. Interlocutory decisions","tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","subs":["(a)"],"by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 2072","url":"https://www.law.cornell.edu/uscode/text/28/2072","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","subs":["(c)"],"by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 256","url":"https://www.law.cornell.edu/uscode/text/29/256","subs":["(b)"],"by":{"0":""}}]};